#define BrotliStoreMetaBlockHeader BrotliStoreMetaBlockHeader_two_pass
#define RewindBitPosition RewindBitPosition_two_pass
#define Hash Hash_two_pass
#define HashBytesAtOffset HashBytesAtOffset_two_pass
#define IsMatch IsMatch_two_pass
#define BuildAndStoreCommandPrefixCode BuildAndStoreCommandPrefixCode_two_pass
#define EmitInsertLen EmitInsertLen_two_pass
#define EmitCopyLen EmitCopyLen_two_pass
#define EmitCopyLenLastDistance EmitCopyLenLastDistance_two_pass
#define EmitDistance EmitDistance_two_pass
#define EmitUncompressedMetaBlock EmitUncompressedMetaBlock_two_pass
#define ShouldCompress ShouldCompress_two_pass
