#undef RewindBitPosition
#undef Hash
#undef HashBytesAtOffset
#undef IsMatch
#undef BuildAndStoreCommandPrefixCode
#undef EmitInsertLen
#undef EmitCopyLen
#undef EmitCopyLenLastDistance
#undef EmitDistance
#undef EmitUncompressedMetaBlock
#undef ShouldCompress
